// called on every request
function recordRequest(req, durationMs) {
  metrics.histogram('http_request_duration_ms', durationMs, {
    method: req.method,
    path: req.url,                  // full URL including query string
    user_id: req.user.id,           // who made the request
    status: String(req.statusCode),
  });
}
